<?php
declare(strict_types=1);
namespace App\Modules\Tenancy\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Tenancy\Services\OfficineAccess as Access;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class SupportAssignmentController extends Controller {
 private function coordinator(Request $r): void {abort_unless(((bool)$r->user()->is_support_coordinator && (bool)$r->user()->internal_active),403,'Coordination requise.');}
 private function rows(int $id) {return DB::table('officine_support_assignments as a')->join('users','users.id','=','a.user_id')->where('a.officine_id',$id)->orderByDesc('a.id')->get(['a.id','a.user_id','users.name','a.scope','a.permissions','a.starts_on','a.ends_on','a.status','a.decision_reason','a.decided_at','a.version','a.created_at'])->map(function($a){$a->permissions=json_decode($a->permissions,true);$a->response_expires_at=\Illuminate\Support\Carbon::parse($a->created_at)->addDays(config('socle.support_pending_days',14))->toIso8601String();$a->expired=$a->status==='pending'&&(now()->gte($a->response_expires_at)||$a->ends_on<now('Africa/Porto-Novo')->toDateString());return $a;});}
 public function index(Request $r){$id=Access::admin($r);return response()->json(['data'=>$this->rows($id)]);}
 public function directory(Request $r){$this->coordinator($r);return response()->json(['officines'=>DB::table('officines')->where('status','active')->orderBy('name')->get(['id','name']),'staff'=>DB::table('users')->where('is_support_staff',true)->where('internal_active',true)->where('is_active',true)->orderBy('name')->get(['id','name'])]);}
 public function platformIndex(Request $r,string $officeId){$this->coordinator($r);abort_unless(DB::table('officines')->where('id',$officeId)->exists(),404);return response()->json(['data'=>$this->rows((int)$officeId)]);}
 public function propose(Request $r,string $officeId){
  $this->coordinator($r);$d=$r->validate(['user_id'=>['required','integer'],'scope'=>['required','string','max:150','regex:/\S/u'],'permissions'=>['required','array','min:1','max:4'],'permissions.*'=>['required','string','distinct',Rule::in(Access::SUPPORT_PERMISSIONS)],'starts_on'=>['required','date_format:Y-m-d'],'ends_on'=>['required','date_format:Y-m-d','after_or_equal:starts_on'],'request_key'=>['required','string','max:80','regex:/^[a-zA-Z0-9-]{16,80}$/']]);
  $result=DB::transaction(function()use($r,$officeId,$d){$o=DB::table('officines')->where('id',$officeId)->lockForUpdate()->first();abort_unless($o,404);abort_unless($o->status==='active',409,'Officine non active.');abort_unless(DB::table('users')->where('id',$d['user_id'])->where('is_support_staff',true)->where('internal_active',true)->where('is_active',true)->exists(),422,'Accompagnateur non éligible.');
   $existing=DB::table('officine_support_assignments')->where('officine_id',$officeId)->where('request_key',$d['request_key'])->first();if($existing){$same=$existing->proposed_by===$r->user()->id&&$existing->user_id===(int)$d['user_id']&&$existing->scope===$d['scope']&&$existing->starts_on===$d['starts_on']&&$existing->ends_on===$d['ends_on']&&json_decode($existing->permissions,true)===$d['permissions'];abort_unless($same,409,'Clé déjà utilisée avec un autre contenu.');return $existing->id;}
   abort_if(DB::table('officine_support_assignments')->where('officine_id',$officeId)->where('user_id',$d['user_id'])->where(fn($q)=>$q->where('status','approved')->orWhere(fn($q)=>$q->where('status','pending')->where('created_at','>',now()->subDays(config('socle.support_pending_days',14)))))->where('ends_on','>=',now('Africa/Porto-Novo')->toDateString())->exists(),409,'Une affectation est déjà en attente ou active.');
   $id=DB::table('officine_support_assignments')->insertGetId(array_merge($d,['officine_id'=>(int)$officeId,'proposed_by'=>$r->user()->id,'permissions'=>json_encode($d['permissions']),'created_at'=>now(),'updated_at'=>now()]));Access::audit($r,(int)$officeId,'support.proposed',['assignment_id'=>$id]);\App\Modules\Identity\Services\Outbox::office((int)$officeId,'support-proposed:'.$id,'Nouvel accompagnateur proposé','Consultez la portée et la période avant de décider.');return $id;
  });return response()->json(['id'=>$result],201);
 }
 public function decide(Request $r,string $assignmentId){
  $id=Access::admin($r);$d=$r->validate(['decision'=>['required',Rule::in(['approved','refused','revoked','changes_requested'])],'version'=>['required','integer','min:1'],'reason'=>['nullable','string','max:2000']]);
  DB::transaction(function()use($r,$id,$assignmentId,$d){Access::lockAdmin($r,$id);$a=DB::table('officine_support_assignments')->where('officine_id',$id)->where('id',$assignmentId)->lockForUpdate()->first();abort_unless($a,404);abort_if($a->user_id===$r->user()->id,403,'Auto-approbation interdite.');abort_unless($a->version===(int)$d['version'],409,'Version périmée. Rechargez les accès.');
   abort_unless(($a->status==='pending'&&in_array($d['decision'],['approved','refused','changes_requested'],true))||($a->status==='approved'&&$d['decision']==='revoked'),409,'Décision incompatible avec l’état actuel.');
   if($d['decision']!=='approved')abort_unless(trim($d['reason']??'')!=='',422,'Un motif est obligatoire.');
   if($d['decision']==='approved'){abort_unless(now()->lt(\Illuminate\Support\Carbon::parse($a->created_at)->addDays(config('socle.support_pending_days',14))),409,'Proposition expirée.');abort_unless($a->ends_on>=now('Africa/Porto-Novo')->toDateString(),409,'La proposition a expiré.');abort_unless(DB::table('users')->where('id',$a->user_id)->where('is_support_staff',true)->where('internal_active',true)->where('is_active',true)->exists(),409,'Accompagnateur non éligible.');}
   DB::table('officine_support_assignments')->where('id',$a->id)->update(['status'=>$d['decision'],'decision_reason'=>trim($d['reason']??'')?:null,'decided_by'=>$r->user()->id,'decided_at'=>now(),'version'=>$a->version+1,'updated_at'=>now()]);Access::audit($r,$id,'support.'.$d['decision'],['assignment_id'=>$a->id,'version'=>$a->version+1]);\App\Modules\Identity\Services\Outbox::push($a->user_id,'support-decision:'.$a->id.':'.($a->version+1),'Décision sur votre affectation','État : '.$d['decision'],$id);if($a->proposed_by!==$a->user_id)\App\Modules\Identity\Services\Outbox::push($a->proposed_by,'support-coordinator-decision:'.$a->id.':'.($a->version+1),'Décision sur une proposition','Une décision a été prise sur votre proposition. Consultez la coordination.',$id);
  });return response()->json(['message'=>'Décision enregistrée.']);
 }

 public function end(Request $r,string $officeId,string $assignmentId){$this->coordinator($r);$d=$r->validate(['version'=>['required','integer','min:1'],'reason'=>['required','string','max:2000','regex:/\S/u']]);DB::transaction(function()use($r,$officeId,$assignmentId,$d){DB::table('officines')->where('id',$officeId)->lockForUpdate()->firstOrFail();$a=DB::table('officine_support_assignments')->where('officine_id',$officeId)->where('id',$assignmentId)->lockForUpdate()->first();abort_unless($a,404);abort_unless($a->version===(int)$d['version']&&in_array($a->status,['approved','pending'],true),409);DB::table('officine_support_assignments')->where('id',$a->id)->update(['status'=>'revoked','version'=>$a->version+1,'decision_reason'=>$d['reason'],'decided_by'=>$r->user()->id,'decided_at'=>now(),'updated_at'=>now()]);Access::audit($r,(int)$officeId,'support.revoked',['assignment_id'=>$a->id]);\App\Modules\Identity\Services\Outbox::office((int)$officeId,'support-ended:'.$a->id.':'.($a->version+1),'Accès accompagnateur terminé','La coordination a terminé une affectation.');\App\Modules\Identity\Services\Outbox::push($a->user_id,'support-staff-ended:'.$a->id.':'.($a->version+1),'Fin de votre affectation','Votre accès à une officine a été terminé.',(int)$officeId);});return response()->json(['message'=>'Affectation terminée.']);}
}
